import pathlib
import task as t

def tables(connection):return t.sql(connection,"SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='training' ORDER BY TABLE_NAME")
def receipt(plan,manifest):return{'schema':1,'plan_sha256':t.digest(plan),'manifest_sha256':t.digest(manifest),'target_uuid':plan['target_uuid'],'table_rows':{table:manifest['files'][table]['rows']for table in t.TABLES},'verified':True}
def audit_restore(connection,plan,directory):
    manifest,data=t.load_bundle(plan,directory);path=t.directory(directory)
    with t.borrowed(connection,plan['target_uuid']):
        actual=t.catalog(connection)
        if actual!=manifest['catalog']:raise ValueError('actual target metadata differs')
        for table in t.TABLES:
            if t.rows(connection,table,actual[table])!=[[t.encode(value)for value in row]for row in data[table]]:raise ValueError('actual complete target rows differ')
        # This is a real FK relationship query, independent from artifact-only validation.
        if t.sql(connection,'SELECT COUNT(*) FROM training.linked_probe c JOIN training.gipk_probe p ON p.my_row_id=c.parent_id')[0][0]!=len(data['linked_probe']):raise ValueError('actual target relationship differs')
        report=receipt(plan,manifest)
        if(path/'report.json').exists():
            if t.canonical(t.read_json(path/'report.json'))!=t.canonical(report):raise ValueError('existing report differs')
        else:t.publish(path/'report.json',report)
        return report
def restore_snapshot(connection,plan,directory,checkpoint=None):
    manifest,data=t.load_bundle(plan,directory);path=t.directory(directory)
    if checkpoint is not None and not callable(checkpoint):raise ValueError('callable checkpoint required')
    with t.borrowed(connection,plan['target_uuid']):
        if tables(connection):raise ValueError('approved target must be empty; partial targets are never replayed/dropped')
        stage='create'
        try:
            for table in t.TABLES:
