                if table=='gipk_probe':t.sql(connection,'ALTER TABLE training.gipk_probe AUTO_INCREMENT=%s',(manifest['catalog'][table]['properties'][2],))
                if checkpoint is not None:checkpoint('after_create',table)
            if t.catalog(connection)!=manifest['catalog']:raise ValueError('created approved schema differs')
            stage='insert'
            for table in t.TABLES:
                columns=[row[0]for row in manifest['catalog'][table]['columns']]
